inputs.manifest:
{
  "schema_version": "1.0.0",
  "id": "qwen-image/t2i",
  "label": {
    "en": "Generate",
    "ru": "Генерация"
  },
  "family": "qwen-image",
  "family_label": "Qwen Image",
  "mode": "t2i",
  "order": 10,
  "controls": [
    {
      "param": "prompt",
      "kind": "prompt",
      "superprompt": true
    },
    {
      "param": "size",
      "kind": "size",
      "aspects": [
        "1:1",
        "16:9",
        "9:16",
        "3:2",
        "2:3",
        "4:3",
        "3:4"
      ],
      "width_param": "width",
      "height_param": "height",
      "base_mp": 1.6,
      "mp": [
        0.25,
        4.0
      ],
      "snap": 16
    },
    {
      "param": "seed",
      "kind": "seed"
    },
    {
      "param": "loras",
      "kind": "loras",
      "max": 8,
      "strength": [
        -2.0,
        2.0
      ]
    },
    {
      "param": "negative_prompt",
      "kind": "prompt",
      "advanced": true,
      "label": {
        "en": "Negative prompt",
        "ru": "Негативный промпт"
      }
    },
    {
      "param": "steps",
      "kind": "number",
      "advanced": true,
      "min": 1,
      "max": 60,
      "step": 1,
      "label": {
        "en": "Steps",
        "ru": "Шаги"
      }
    },
    {
      "param": "cfg",
      "kind": "number",
      "advanced": true,
      "min": 0,
      "max": 15,
      "step": 0.1,
      "label": {
        "en": "CFG",
        "ru": "CFG"
      }
    }
  ],
  "refs": {
    "max": 0
  },
  "negative_prompt": true,
  "models": [
    {
      "title": "studio:model",
      "input": "unet_name",
      "folder": "diffusion_models",
      "match": "qwen_image_(2512|\\d+)_|Artius_Qwen_v"
    },
    {
      "title": "studio:clip",
      "input": "clip_name",
      "folder": "text_encoders",
      "match": "qwen_2\\.5_vl_7b"
    },
    {
      "title": "studio:vae",
      "input": "vae_name",
      "folder": "vae",
      "match": "qwen_image_vae"
    }
  ]
}
